const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-classification-backfill", node: "Code: Acquire Backfill Lock" } });
const redis = require('redis');
const crypto = require('crypto');
// Same lock key as alice-dms-processor — the two must never run concurrently (Ollama/TITAN X contention).
const LOCK_KEY = 'alice:dms:processor:lock:run';
const LOCK_TTL_MS = 1800000;

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
const ownerToken = crypto.randomUUID();
let acquired = false, lockError = false;
try {
  await client.connect();
  const res = await client.set(LOCK_KEY, JSON.stringify({ owner: ownerToken, started_at: new Date().toISOString() }), { NX: true, PX: LOCK_TTL_MS });
  acquired = (res === 'OK');
} catch(e) {
  logger.info('[Backfill] Lock acquire error: ' + e.message);
  acquired = false; lockError = true;
} finally {
  await client.quit().catch(() => {});
}

return [{ json: { _lock_acquired: acquired, _lock_error: lockError, lock_owner: acquired ? ownerToken : null } }];

