const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-classification-backfill", node: "Code: Fetch All Documents" } });
const axios = require('axios');
const trigger = $input.first().json;
const WEAVIATE = 'http://weaviate:8080';
const PAGE = 100;

const allDocs = [];
for (const col of trigger.collections) {
  let cursor = null;
  while (true) {
    const cursorClause = cursor ? `, after: "${cursor}"` : '';
    const gql = `{ Get { ${col.class}(limit: ${PAGE}${cursorClause}) { _additional { id } filePath fileHash ${col.textField} } } }`;
    let results;
    try {
      const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: gql }, { headers: { 'Content-Type': 'application/json' }, timeout: 30000 });
      if (r.data?.errors) {
        logger.warn(`[Backfill] GraphQL error for ${col.class}: ${JSON.stringify(r.data.errors)}`);
        break;
      }
      results = r.data?.data?.Get?.[col.class] || [];
    } catch(e) {
      logger.warn(`[Backfill] Request failed for ${col.class}: ${e.message}`);
      break;
    }
    if (results.length === 0) break;
    for (const doc of results) {
      allDocs.push({
        weaviate_id: doc._additional?.id,
        class: col.class,
        filePath: doc.filePath || null,
        fileHash: doc.fileHash || null,
        plaintext: doc[col.textField] || '',
        confirm: trigger.confirm
      });
    }
    if (results.length < PAGE) break;
    cursor = results[results.length - 1]?._additional?.id;
    if (!cursor) break;
  }
  logger.info(`[Backfill] ${col.class}: fetched ${allDocs.filter(d => d.class === col.class).length} documents`);
}

logger.info(`[Backfill] Total documents queued for reclassification: ${allDocs.length}`);
if (allDocs.length === 0) {
  return [{ json: { _empty: true } }];
}
return allDocs.map(d => ({ json: { ...d, _empty: false } }));

