function toISODate(val) {
  if (!val) return null;
  try { const d = new Date(val); if (isNaN(d.getTime())) return null; return d.toISOString(); } catch(e) { return null; }
}
function toNum(val) {
  if (val === null || val === undefined || val === '') return null;
  const n = parseFloat(val);
  return isNaN(n) ? null : n;
}

const prompts = {
