function buildProperties(docType, extracted, fileName, filePath, fileHash, fullText, confidence, uncertain) {
  const now = new Date().toISOString();
  let properties = {};
  if (docType === 'Invoice') {
    properties = { issuer: extracted.issuer || null, recipient: extracted.recipient || null, invoiceNumber: extracted.invoiceNumber || null, invoiceDate: toISODate(extracted.invoiceDate), dueDate: toISODate(extracted.dueDate), amountGross: toNum(extracted.amountGross), amountNet: toNum(extracted.amountNet), vatRate: toNum(extracted.vatRate), currency: extracted.currency || 'EUR', lineItems: extracted.lineItems ? JSON.stringify(extracted.lineItems) : null, summary: extracted.summary || null, fullText, fileName, filePath, fileHash, classificationConfidence: confidence, classificationUncertain: uncertain, createdBy: 'alice-dms-classification-backfill', createdAt: now, updatedAt: now };
  } else if (docType === 'BankStatement') {
    properties = { bankName: extracted.bankName || null, accountHolder: extracted.accountHolder || null, iban: extracted.iban || null, periodFrom: toISODate(extracted.periodFrom), periodTo: toISODate(extracted.periodTo), openingBalance: toNum(extracted.openingBalance), closingBalance: toNum(extracted.closingBalance), currency: extracted.currency || 'EUR', transactions: extracted.transactions ? JSON.stringify(extracted.transactions) : null, summary: extracted.summary || null, fullText, fileName, filePath, fileHash, classificationConfidence: confidence, classificationUncertain: uncertain, createdBy: 'alice-dms-classification-backfill', createdAt: now };
  } else if (docType === 'Email') {
    properties = { subject: extracted.subject || null, sender: extracted.sender || null, recipients: Array.isArray(extracted.recipients) ? extracted.recipients : (extracted.recipients ? [extracted.recipients] : []), date: toISODate(extracted.date), summary: extracted.summary || null, content: fullText, fileName, filePath, fileHash, classificationConfidence: confidence, classificationUncertain: uncertain, createdBy: 'alice-dms-classification-backfill', createdAt: now };
  } else if (docType === 'SecuritySettlement') {
    properties = { bank: extracted.bank || null, depotNumber: extracted.depotNumber || null, transactionDate: toISODate(extracted.transactionDate), securityName: extracted.securityName || null, isin: extracted.isin || null, transactionType: extracted.transactionType || null, quantity: toNum(extracted.quantity), price: toNum(extracted.price), settlementAmount: toNum(extracted.settlementAmount), settlementCurrency: extracted.settlementCurrency || 'EUR', summary: extracted.summary || null, fullText, fileName, filePath, fileHash, classificationConfidence: confidence, classificationUncertain: uncertain, createdBy: 'alice-dms-classification-backfill', createdAt: now };
  } else if (docType === 'Contract') {
    properties = { contractType: extracted.contractType || null, contractPartner: extracted.contractPartner || null, signDate: toISODate(extracted.signDate), startDate: toISODate(extracted.startDate), endDate: toISODate(extracted.endDate), noticePeriod: extracted.noticePeriod || null, monthlyCost: toNum(extracted.monthlyCost), annualCost: toNum(extracted.annualCost), currency: extracted.currency || 'EUR', summary: extracted.summary || null, fullText, fileName, filePath, fileHash, classificationConfidence: confidence, classificationUncertain: uncertain, createdBy: 'alice-dms-classification-backfill', createdAt: now, updatedAt: now };
  } else {
    properties = { title: extracted.title || fileName, sender: extracted.sender || null, recipient: extracted.recipient || null, documentDate: toISODate(extracted.documentDate), tags: Array.isArray(extracted.tags) ? extracted.tags : [], summary: extracted.summary || null, fullText, fileName, filePath, fileHash, classificationConfidence: confidence, classificationUncertain: uncertain, createdBy: 'alice-dms-classification-backfill', createdAt: now, updatedAt: now };
  }
  return Object.fromEntries(Object.entries(properties).filter(([_, v]) => v !== null && v !== undefined));
}

async function cascadeDeleteBankTransactions(parentId) {
  let deleted = 0;
  if (!parentId) return deleted;
  const safePid = String(parentId).replace(/[^a-zA-Z0-9-]/g, '');
  if (!safePid || safePid !== parentId) return deleted;
  const PAGE = 100;
  while (true) {
    const gql = `{ Get { BankTransaction(where: { path: ["parentStatementId"], operator: Equal, valueText: "${safePid}" }, limit: ${PAGE}) { _additional { id } } } }`;
    let ids = [];
    try {
      const r = await axios.post(`${WEAVIATE_URL}/v1/graphql`, { query: gql }, { headers: { 'Content-Type': 'application/json' }, timeout: 15000 });
      ids = (r.data?.data?.Get?.BankTransaction || []).map(h => h?._additional?.id).filter(Boolean);
    } catch(e) { break; }
    if (ids.length === 0) break;
    for (const id of ids) {
      try { await axios.delete(`${WEAVIATE_URL}/v1/objects/BankTransaction/${id}`, { timeout: 10000 }); deleted++; } catch(e) {}
    }
    if (ids.length < PAGE) break;
  }
  return deleted;
}

function normDirection(val) { if (!val) return null; const v = String(val).toLowerCase().trim(); if (['credit','eingang','in','gutschrift','+'].includes(v)) return 'credit'; if (['debit','ausgang','out','lastschrift','belastung','-'].includes(v)) return 'debit'; return null; }

async function extractBankTransactions(plaintext, parentId, bankName, accountIban, statementCurrency) {
  const CHUNK_SIZE = 8000;
  function splitChunks(text, maxLen) {
    if (!text) return [];
    if (text.length <= maxLen) return [text];
    const chunks = []; let start = 0;
    while (start < text.length) {
      let end = Math.min(start + maxLen, text.length);
      if (end < text.length) { const lastNl = text.lastIndexOf('\n', end); if (lastNl > start + Math.floor(maxLen / 2)) end = lastNl + 1; }
      chunks.push(text.slice(start, end)); start = end;
    }
    return chunks;
  }
  const header = 'You are a bank-statement transaction extractor. From the following text fragment of a bank statement, extract every individual booking line as a JSON array. Respond ONLY with a JSON object {"transactions": [...]} — no prose, no explanation.\n\nEach element MUST be an object with these fields:\n  "transactionDate":  "YYYY-MM-DD"  (booking date, required)\n  "valueDate":        "YYYY-MM-DD"  (Wertstellung, optional, null if absent)\n  "amount":           number         (always POSITIVE, sign goes into direction)\n  "currency":         string         (e.g. "EUR")\n  "direction":        "credit" or "debit"  (credit = Eingang/Gutschrift, debit = Ausgang/Lastschrift)\n  "counterparty":     string         (sender name on credits, recipient name on debits)\n  "purpose":          string         (Verwendungszweck / booking text; empty string if absent)\n  "counterpartyIban": string or null (IBAN of the other side if present)\n  "balanceAfter":     number or null (account balance after this booking if present)\n  "rawText":          string         (the original booking line as-is)\n\nDates must be ISO format YYYY-MM-DD. Numbers must be plain JSON numbers. If no transactions are visible, return {"transactions": []}.\n\nText fragment:\n';
  async function extractChunk(chunkText) {
    const resp = await axios.post('http://ollama-3090:11434/api/generate', { model: ollamaModel, prompt: header + chunkText, stream: false, format: 'json', options: { temperature: 0, num_predict: 10000 } }, { timeout: 300000 });
    const parsed = JSON.parse(resp.data?.response || '{}');
    if (!Array.isArray(parsed.transactions)) throw new Error('missing transactions array');
    return parsed.transactions;
  }
  const chunks = splitChunks(plaintext, CHUNK_SIZE);
  let allTx = [];
  for (const chunkText of chunks) {
    try { allTx.push(...await extractChunk(chunkText)); }
    catch(e1) { try { allTx.push(...await extractChunk(chunkText)); } catch(e2) { /* drop chunk */ } }
  }
  const seen = new Set(); const dedup = [];
  for (const tx of allTx) {
    const key = `${tx.transactionDate||''}|${tx.amount!=null?String(tx.amount):''}|${(tx.counterparty||'').trim().toLowerCase()}`;
    if (seen.has(key)) continue; seen.add(key); dedup.push(tx);
  }
  const now = new Date().toISOString();
  const objects = [];
  for (const tx of dedup) {
    const txDate = toISODate(tx.transactionDate);
    if (!txDate) continue;
    const amt = toNum(tx.amount);
    const props = { parentStatementId: parentId, transactionDate: txDate, valueDate: toISODate(tx.valueDate), amount: amt != null ? Math.abs(amt) : null, currency: tx.currency || statementCurrency, direction: normDirection(tx.direction), counterparty: (tx.counterparty || '').toString(), purpose: (tx.purpose || '').toString().trim() || null, counterpartyIban: tx.counterpartyIban || null, balanceAfter: toNum(tx.balanceAfter), bankName, accountIban, rawText: (tx.rawText || '').toString(), createdBy: 'alice-dms-classification-backfill', createdAt: now };
    objects.push({ class: 'BankTransaction', properties: Object.fromEntries(Object.entries(props).filter(([_, v]) => v !== null && v !== undefined)) });
  }
  if (objects.length > 0) {
    try { await axios.post(`${WEAVIATE_URL}/v1/batch/objects`, { objects }, { headers: { 'Content-Type': 'application/json' }, timeout: 60000 }); } catch(e) { logger.warn('[Backfill] BankTransaction batch insert failed: ' + e.message); }
  }
  return objects.length;
}

try {
  await incr('checked', 1);

  const proposedType = validTypes.includes(classifyResult.document_type) ? classifyResult.document_type : doc.class;
  const fileName = (doc.filePath || '').split('/').pop();

  if (proposedType === doc.class) {
    return [{ json: { _outcome: 'no_deviation', filePath: doc.filePath } }];
  }

  await incr('deviations_found', 1);

  if (!doc.confirm) {
    await client.rPush('alice:dms:backfill:run:deviations', JSON.stringify({
      fileName, filePath: doc.filePath, currentCollection: doc.class, proposedCollection: proposedType, confidence: classifyResult.confidence
    }));
    return [{ json: { _outcome: 'deviation_reported', filePath: doc.filePath, currentCollection: doc.class, proposedCollection: proposedType } }];
  }

  // Confirm mode: re-extract with the target type's prompt and migrate
  const promptText = (prompts[proposedType] || prompts['Document']) + (doc.plaintext || '').slice(0, 20000);
  let extracted = {};
  try {
    const resp = await axios.post('http://ollama-3090:11434/api/generate', { model: ollamaModel, prompt: promptText, stream: false, format: 'json', options: { temperature: 0 } }, { timeout: 300000 });
    extracted = JSON.parse(resp.data?.response || '{}');
  } catch(e) {
    throw new Error('extraction_failed: ' + e.message);
  }

  const properties = buildProperties(proposedType, extracted, fileName, doc.filePath, doc.fileHash, (doc.plaintext || '').slice(0, 10000), classifyResult.confidence, !!classifyResult.uncertain);

  const insertResp = await axios.post(`${WEAVIATE_URL}/v1/objects`, { class: proposedType, properties }, { headers: { 'Content-Type': 'application/json' }, timeout: 15000 });
  const newId = insertResp.data?.id;
  if (!newId) throw new Error('weaviate_insert_failed');

  await axios.delete(`${WEAVIATE_URL}/v1/objects/${doc.class}/${doc.weaviate_id}`, { timeout: 10000 }).catch(e => { logger.warn('[Backfill] Old object delete failed: ' + e.message); });

  // BankStatement special case: transaction children follow the parent
  if (doc.class === 'BankStatement') {
    const deleted = await cascadeDeleteBankTransactions(doc.weaviate_id);
    if (deleted > 0) logger.info(`[Backfill] Cascade-deleted ${deleted} BankTransactions of old parent ${doc.weaviate_id}`);
  }
  if (proposedType === 'BankStatement') {
    const txCount = await extractBankTransactions(doc.plaintext || '', newId, extracted.bankName || null, extracted.iban || null, extracted.currency || 'EUR');
    logger.info(`[Backfill] Extracted ${txCount} BankTransactions for new parent ${newId}`);
  }

  // Reuse existing thumbnail-regeneration mechanism (alice-dms-thumbnailer), not rebuilt here
  try {
    await axios.post('http://alice-dms-thumbnailer:8004/generate', {
      original_path: doc.filePath, weaviate_uuid: newId, document_type: proposedType,
      file_type: (doc.filePath || '').split('.').pop().toLowerCase()
    }, { headers: { 'Content-Type': 'application/json' }, timeout: 120000 });
  } catch(e) {
    logger.warn('[Backfill] Thumbnail regeneration failed for ' + newId + ': ' + e.message);
  }

  await incr('migrated', 1);
  return [{ json: { _outcome: 'migrated', fileName, filePath: doc.filePath, currentCollection: doc.class, proposedCollection: proposedType } }];

} catch(e) {
  logger.warn('[Backfill] Migration failed for ' + (doc.filePath || '') + ': ' + e.message);
  await incr('failed', 1);
  return [{ json: { _outcome: 'failed', filePath: doc.filePath, error: e.message } }];
} finally {
  await client.quit().catch(() => {});
}

