const trigger = $('Code: Init Backfill Run').first().json;
const startTimeStr = await client.get('alice:dms:backfill:run:start_time');
const stats = await client.hGetAll('alice:dms:backfill:run:stats');
const runtime_seconds = startTimeStr ? Math.floor((Date.now() - parseInt(startTimeStr)) / 1000) : 0;

let deviations = [];
if (!trigger.confirm) {
  const raw = await client.lRange('alice:dms:backfill:run:deviations', 0, -1);
  deviations = raw.map(s => { try { return JSON.parse(s); } catch(e) { return null; } }).filter(Boolean);
}

await client.del('alice:dms:backfill:run:start_time').catch(() => {});
await client.del('alice:dms:backfill:run:stats').catch(() => {});
await client.del('alice:dms:backfill:run:deviations').catch(() => {});

const owner = $('Code: Acquire Backfill Lock').first().json.lock_owner;
const RELEASE_SCRIPT = `local raw = redis.call('GET', KEYS[1]) if not raw then return 0 end local ok, data = pcall(cjson.decode, raw) if not ok or data.owner ~= ARGV[1] then return 0 end redis.call('DEL', KEYS[1]) return 1`;
try { await client.eval(RELEASE_SCRIPT, { keys: ['alice:dms:processor:lock:run'], arguments: [owner] }); } catch(e) {}
await client.quit().catch(() => {});

const item = $input.first().json || {};
const reason = item._lock_lost ? 'lock_lost' : (item._time_limit_reached ? 'time_limit_reached' : 'completed');

const result = {
  mode: trigger.confirm ? 'confirm' : 'dry-run',
  reason,
  total_checked: parseInt(stats.checked || '0'),
  deviations_found: parseInt(stats.deviations_found || '0'),
  runtime_seconds
};
if (trigger.confirm) {
  result.migrated = parseInt(stats.migrated || '0');
  result.failed = parseInt(stats.failed || '0');
} else {
  result.deviations = deviations;
}
logger.info(JSON.stringify({ event: 'alice-dms-classification-backfill-complete', ...result }));
return [{ json: result }];
